6	{"id": "captions-burned-in", "name": "Captions burn in with no extra step", "summary": "The preview, a rendered frame and an exported movie all show captions, because they are part of the picture.", "page": "captions/how-captions-work", "anchor": "captions-burn-in-with-no-extra-step", "where": "Preview"}
7	{"id": "caption-two-kinds", "name": "Two kinds of caption: subtitles and word captions", "summary": "A run makes either classic two-line subtitles or large word-by-word captions in one of five styles, where each word lights up as it is said.", "page": "captions/how-captions-work", "anchor": "two-kinds-of-caption-subtitles-and-word-captions", "where": "File ▸ Generate Captions… ▸ Style"}
8	{"id": "caption-track-naming", "name": "Caption track names", "summary": "The first caption track is named Captions, then Captions 2, Captions 3 and so on, so separate runs can be told apart in the track headers.", "page": "captions/how-captions-work", "anchor": "caption-track-names", "where": "Timeline track headers"}
9	{"id": "caption-track-never-guessed", "name": "A caption track is never guessed", "summary": "Nothing in a project marks a track as the caption track, so a command that needs one is told which, or asks.", "page": "captions/how-captions-work", "anchor": "a-caption-track-is-never-guessed", "where": "File ▸ Export Captions… ▸ Track"}
10	{"id": "caption-frame-grid-and-overlap", "name": "Frame grid and no overlaps", "summary": "Every caption time snaps to the project frame grid, and captions on one track never overlap.", "page": "captions/how-captions-work", "anchor": "frame-grid-and-no-overlaps", "where": "File ▸ Import Captions…"}
11	{"id": "captions-in-a-nest", "name": "Captions inside a nest", "summary": "The caption commands work on the timeline you have open, so with a nest open they work inside that nest.", "page": "captions/how-captions-work", "anchor": "captions-inside-a-nest", "where": "File ▸ Import Captions…"}
12	{"id": "import-captions", "name": "Import Captions", "summary": "File ▸ Import Captions… reads a SubRip (.srt) file onto a new caption track, one text clip per cue, as a single undo step.", "page": "captions/import-captions", "anchor": "import-captions", "where": "File ▸ Import Captions…"}
13	{"id": "import-tolerated-variations", "name": "What the reader tolerates", "summary": "The reader copes with the variations real SubRip files have, rather than refusing them.", "page": "captions/import-captions", "anchor": "file-variations-it-copes-with", "where": "File ▸ Import Captions…"}
14	{"id": "import-markup-stripped", "name": "Markup stripped on import", "summary": "Formatting tags and overrides are removed and common HTML entities are decoded.", "page": "captions/import-captions", "anchor": "what-happens-to-the-text", "where": "File ▸ Import Captions…"}
15	{"id": "import-line-breaks", "name": "Line breaks kept", "summary": "The file's own line breaks are kept, and long lines also wrap inside the caption box.", "page": "captions/import-captions", "anchor": "what-happens-to-the-text", "where": "File ▸ Import Captions…"}
16	{"id": "import-malformed-reported", "name": "Malformed entries are reported", "summary": "Bad entries are skipped and listed by line number, never dropped silently.", "page": "captions/import-captions", "anchor": "malformed-entries-are-reported", "where": "File ▸ Import Captions…"}
17	{"id": "import-unreadable-file", "name": "A file with no readable cue is refused", "summary": "A file in which no cue can be read is refused, and the message gives the first few reasons.", "page": "captions/import-captions", "anchor": "when-a-file-cant-be-read", "where": "File ▸ Import Captions…"}
