25	{"id": "generate-remembers-choices", "name": "The sheet remembers its choices", "summary": "Generate Captions reopens with your last engine, Style and three look boxes.", "page": "captions/generate-captions", "anchor": "what-the-sheet-remembers", "where": "File ▸ Generate Captions…"}
26	{"id": "generate-summary-note", "name": "Summary line and note", "summary": "Under the grid a summary gives the size of the run, and a note explains anything stopping it.", "page": "captions/generate-captions", "anchor": "read-the-summary-and-the-note", "where": "File ▸ Generate Captions…"}
27	{"id": "generate-progress", "name": "Progress", "summary": "While a run goes, the card shows a progress bar, \"Transcribing N clips…\" and a detail line.", "page": "captions/generate-captions", "anchor": "follow-a-run", "where": "File ▸ Generate Captions… ▸ progress"}
28	{"id": "generate-cancel", "name": "Cancel a run", "summary": "Cancel stops a run, closing the sheet mid-run also stops it, and nothing is placed.", "page": "captions/generate-captions", "anchor": "cancel-a-run", "where": "File ▸ Generate Captions… ▸ Cancel"}
29	{"id": "generate-run-report", "name": "The run report", "summary": "Placing the captions is one undo step, and a run with something to report keeps the card open to say so.", "page": "captions/generate-captions", "anchor": "the-run-report", "where": "File ▸ Generate Captions…"}
30	{"id": "generate-for-agents", "name": "Generating captions from an agent", "summary": "The transcribe tool does what the sheet does, and also answers the cues so an agent can check them before placing anything.", "page": "captions/generate-captions", "anchor": "with-an-agent", "where": "MCP tool transcribe"}
31	{"id": "transcribable-clips", "name": "Which clips can be transcribed", "summary": "A clip can be transcribed only if it plays a movie or sound file that has an audio track, its audio is on, and its file is present.", "page": "captions/what-can-be-transcribed", "anchor": "which-clips-can-be-transcribed", "where": "File ▸ Generate Captions…"}
32	{"id": "transcribe-skip-reasons", "name": "Why a clip is skipped", "summary": "Each clip left out of a run is named with one of a fixed set of reasons.", "page": "captions/what-can-be-transcribed", "anchor": "why-a-clip-is-skipped", "where": "File ▸ Generate Captions…"}
33	{"id": "captions-on-retimed-clips", "name": "Retimed clips land correctly", "summary": "On a sped-up, slowed or speed-ramped clip, each word lands where it is heard on the timeline.", "page": "captions/what-can-be-transcribed", "anchor": "retimed-clips-land-correctly", "where": "File ▸ Generate Captions…"}
34	{"id": "transcribe-run-limits", "name": "The 10-hour and 4,096-clip limits", "summary": "A run is refused before anything changes if it would break a limit.", "page": "captions/what-can-be-transcribed", "anchor": "the-10-hour-and-4096-clip-limits", "where": "File ▸ Generate Captions…", "needs": "your AssemblyAI key"}
