36	{"id": "on-device-no-permission", "name": "No permission prompt", "summary": "Transcribing on this Mac asks for no system grant, because the engine reads an extracted audio file rather than the microphone.", "page": "captions/on-device-transcription", "anchor": "transcribe-on-this-mac", "where": "File ▸ Generate Captions…"}
37	{"id": "on-device-languages", "name": "On-device languages", "summary": "The Language pop-up lists every locale this Mac's speech engine supports, marking those whose model is missing.", "page": "captions/on-device-transcription", "anchor": "choose-a-language", "where": "File ▸ Generate Captions… ▸ Language"}
38	{"id": "download-speech-language", "name": "Download a speech language", "summary": "A language whose model is missing can be installed from a Download button under the Language pop-up.", "page": "captions/on-device-transcription", "anchor": "download-a-speech-language", "where": "File ▸ Generate Captions… ▸ Download"}
39	{"id": "on-device-no-cache", "name": "No cache for on-device captions", "summary": "Nothing is cached for captions on this Mac: every run, restyling included, recognises the audio again.", "page": "captions/on-device-transcription", "anchor": "every-run-recognises-the-audio-again", "where": "File ▸ Generate Captions…"}
