41	{"id": "assemblyai-engine", "name": "Transcribe with AssemblyAI", "summary": "With Engine set to AssemblyAI, the audio of the files behind your clips goes to AssemblyAI, is transcribed with Universal-3.5 Pro on your own key, and is deleted there once the words are read back.", "page": "captions/assemblyai-transcription", "anchor": "transcribe-with-assemblyai", "where": "File ▸ Generate Captions… ▸ Engine ▸ AssemblyAI", "needs": "your AssemblyAI key"}
