45	{"id": "assemblyai-languages", "name": "Language detection and languages", "summary": "A cloud run can leave the language to Detect automatically, or name one of 21 language codes covering 18 languages.", "page": "captions/assemblyai-transcription", "anchor": "choose-a-language", "where": "File ▸ Generate Captions… ▸ Language", "needs": "your AssemblyAI key"}
46	{"id": "assemblyai-detected-language", "name": "Detected language in the report", "summary": "With Detect automatically, the run report gives each file's detected language and how confident AssemblyAI was.", "page": "captions/assemblyai-transcription", "anchor": "what-the-result-says", "where": "Generate Captions sheet ▸ result lines", "needs": "your AssemblyAI key"}
