51	{"id": "assemblyai-unsaved-project", "name": "Untitled projects", "summary": "An untitled project can be transcribed too: its transcripts stay in a temporary folder until it is saved, then go into the project package.", "page": "captions/assemblyai-transcription", "anchor": "transcribe-an-untitled-project", "where": "File ▸ Generate Captions…", "needs": "your AssemblyAI key"}
