61	{"id": "assemblyai-key-storage", "name": "Where the key is kept", "summary": "The key is saved in a file only you can read, not in the Keychain, and is never passed on the command line.", "page": "captions/assemblyai-key", "anchor": "where-the-key-is-kept", "where": "Frame Job ▸ Settings… (⌘,) ▸ Transcription", "needs": "your AssemblyAI key"}
62	{"id": "assemblyai-key-environment", "name": "A key from the environment", "summary": "If no key is saved, Frame Job also accepts one from the RC_ASSEMBLYAI_KEY environment variable, useful when launching from a terminal.", "page": "captions/assemblyai-key", "anchor": "use-a-key-from-the-environment", "where": "Launch environment", "needs": "your AssemblyAI key"}
