64	{"id": "assemblyai-region", "name": "Region", "summary": "Region chooses the AssemblyAI data centre your audio goes to: United States or European Union.", "page": "captions/assemblyai-key", "anchor": "choose-a-region", "where": "Frame Job ▸ Settings… (⌘,) ▸ Transcription ▸ Region:", "needs": "your AssemblyAI key"}
