68	{"id": "assemblyai-key-person-only", "name": "Only a person sets the key", "summary": "No MCP tool can read or change the key or the region: only a person sets them, in Settings.", "page": "captions/assemblyai-key", "anchor": "only-a-person-sets-the-key", "where": "Frame Job ▸ Settings… (⌘,) ▸ Transcription"}
69	{"id": "subtitles-style", "name": "The Subtitles style", "summary": "The Subtitles style makes classic two-line cues as text clips.", "page": "captions/subtitles", "anchor": "the-subtitles-style", "where": "File ▸ Generate Captions… ▸ Style ▸ Subtitles"}
70	{"id": "subtitles-speaker-colours", "name": "Speaker colours", "summary": "With Speakers on, each speaker's cues take their own colour, in the order the speakers first appear.", "page": "captions/subtitles", "anchor": "speaker-colours", "where": "File ▸ Generate Captions… ▸ Speakers", "needs": "your AssemblyAI key"}
71	{"id": "subtitles-caption-preset", "name": "The Caption preset", "summary": "Each cue uses the Caption text preset, and on a canvas taller than wide the box sits higher.", "page": "captions/subtitles", "anchor": "the-caption-preset", "where": "File ▸ Generate Captions…"}
72	{"id": "word-caption-pages", "name": "Word caption pages", "summary": "The five word styles make the large, one-row captions used in shorts and reels: each clip holds a page of words with each word's timing, and the spoken word is drawn the way the style says.", "page": "captions/word-caption-styles", "anchor": "word-caption-pages", "where": "File ▸ Generate Captions… ▸ Style"}
73	{"id": "style-highlight", "name": "Highlight", "summary": "The spoken word turns yellow and pops to 112%.", "page": "captions/word-caption-styles", "anchor": "highlight", "where": "File ▸ Generate Captions… ▸ Style ▸ Highlight"}
