77	{"id": "style-one-word", "name": "One Word", "summary": "One large word at a time, popping to 120%.", "page": "captions/word-caption-styles", "anchor": "one-word", "where": "File ▸ Generate Captions… ▸ Style ▸ One Word"}
78	{"id": "caption-typefaces", "name": "Bundled typefaces", "summary": "The four display faces ship inside the app under the SIL Open Font License.", "page": "captions/word-caption-styles", "anchor": "bundled-typefaces"}
79	{"id": "pages-filled-by-width", "name": "Pages are filled to their measured width", "summary": "A page is filled to the width it actually measures in its style on your canvas, not to a word count.", "page": "captions/word-caption-styles", "anchor": "pages-are-filled-to-their-measured-width", "where": "File ▸ Generate Captions…"}
80	{"id": "page-breaks", "name": "Where a page breaks", "summary": "A page ends early at natural boundaries in the speech.", "page": "captions/word-caption-styles", "anchor": "where-a-page-breaks", "where": "File ▸ Generate Captions…"}
