83	{"id": "word-style-preview", "name": "The sheet's two-frame preview", "summary": "The preview shows a sample page drawn by the same renderer the canvas uses, at this canvas's proportions.", "page": "captions/word-caption-styles", "anchor": "the-sheets-two-frame-preview", "where": "File ▸ Generate Captions… ▸ preview under Style"}
84	{"id": "word-caption-looks", "name": "Three looks for word captions", "summary": "Three checkboxes under the Style pop-up each add a look to a word style's pages.", "page": "captions/word-caption-looks", "anchor": "three-looks-for-word-captions", "where": "File ▸ Generate Captions… ▸ Slide the pill, Fill words as spoken, Dim in pauses"}
