rows = {r['id']: dict(r) for r in s.get('features', s.get('rows', []))}
f = json.load(open('/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/feature-fixes/captions.json'))
